	/** 
	 * jumpstart the process by instantiating2 Matter
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		matterId = MatterService.getMatterInstance()
		.createMatter( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		MatterService.getMatterInstance()
				.createMatter( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.matterSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Matter : " + successValue.getMatterId());
							  if (successValue.getMatterId().equals(matterId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfMatterList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Matter test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on matter consumed")
					);
			subscriber.matterSubscribe( matterId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Matter : " + successValue.getMatterId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfMatterList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on matter for matterId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Matter. 
	 */
	protected Matter read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Matter" );

		Matter entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Matter with primary key" );
		msg.append( matterId );
		
		MatterFetchOneSummary fetchOneSummary = new MatterFetchOneSummary( matterId );

		try {
			entity = MatterService.getMatterInstance().getMatter( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Matter " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Matter.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Matter." );

		StringBuilder msg = new StringBuilder( "Failed to update a Matter : " );        
		Matter entity = read();
		UpdateMatterCommand command = generateUpdateCommand();
		command.setMatterId(entity.getMatterId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Matter." );

			// for use later on...
			matterId = entity.getMatterId();

			MatterService proxy = MatterService.getMatterInstance();  

			proxy.updateMatter( command ).get();

			LOGGER.info( "-- Successfully saved Matter - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + matterId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Matter.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Matter." );

		Matter entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Matter with id " + matterId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Matter with id " + matterId );

			throw e;
		}

		try{
			MatterService.getMatterInstance().delete( new DeleteMatterCommand( entity.getMatterId() ) ).get();
			LOGGER.info( "-- Successfully deleted Matter with id " + matterId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Matter with id " + matterId );

			throw e;
		}
	}

	/**
	 * get all Matters.
	 */
	protected List<Matter> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Matters:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Matter : " );        
		List<Matter> collection  = new ArrayList<>();

		try {
			// call the static get method on the MatterService
			collection = MatterService.getMatterInstance().getAllMatter();
			assertNotNull( collection, "An Empty collection of Matter was incorrectly returned.");
			
			// Now print out the values
			Matter entity = null;            
			Iterator<Matter> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getMatterId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

